// src/balancing/config/idleVillage/medalPortraitAssets.ts
// Maps a full portrait URL (PgCard, roster bust) to its medallion-ready square.
// Squares are generated by scripts/build-medal-portraits.py into src/assets/portraits/medal/.
// Matching is by file stem, so a new portrait only needs `python scripts/build-medal-portraits.py`.

const fullPortraits = import.meta.glob<string>('@/assets/portraits/*.{png,jpg,jpeg,webp}', {
  eager: true,
  query: '?url',
  import: 'default',
});
const medalSquares = import.meta.glob<string>('@/assets/portraits/medal/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
});

const stemOf = (path: string) =>
  decodeURIComponent(path.split(/[?#]/)[0].split('/').pop() ?? '').replace(/\.[^.]+$/, '');

const medalByStem = new Map<string, string>(
  Object.entries(medalSquares).map(([path, url]) => [stemOf(path), url]),
);

const medalByFullUrl = new Map<string, string>();
for (const [path, url] of Object.entries(fullPortraits)) {
  const medal = medalByStem.get(stemOf(path));
  if (medal) medalByFullUrl.set(url, medal);
}

/**
 * Returns the medallion square for a full portrait URL, or the input when none exists.
 * Exact match first (URLs from the portrait glob), then by file stem so literal paths
 * such as `/assets/portraits/portrait male warrior.png` resolve too.
 */
export function getMedalPortraitUrl(portraitUrl: string): string {
  return medalByFullUrl.get(portraitUrl) ?? medalByStem.get(stemOf(portraitUrl)) ?? portraitUrl;
}

/** Every portrait asset in both versions (full + medal square), for boot warm-up. */
export const ALL_PORTRAIT_ASSET_URLS: readonly string[] = [
  ...Object.values(fullPortraits),
  ...Object.values(medalSquares),
];
